<script setup lang="ts">
import {can,firstAllowed} from './session'
import {useTableWidths} from './tableWidths'
const tableWidths=useTableWidths('FinancePanel')

import {ref,onMounted,onUnmounted,watch} from 'vue'
import {ElMessage} from 'element-plus'
import {api} from './session'
import {displayCurrency} from './currency'
import FinanceSummaryPanel from './FinanceSummaryPanel.vue'
const props=defineProps<{store:string}>(),rows=ref<any[]>([]),summary=ref<any[]>([]),q=ref(''),market=ref(''),markets=ref<string[]>([]),status=ref(''),page=ref(1),pageSize=ref(25),total=ref(0),busy=ref(false),error=ref(''),selected=ref<any>(null),detailOpen=ref(false),view=ref(firstAllowed('finance',['records', 'summary'])),days=ref(1)
const selectedStore=ref(props.store),stores=ref<string[]>([]),fx=ref<any>(null)
const money=(v:any)=>v==null?'—':new Intl.NumberFormat('zh-CN',{style:'currency',currency:displayCurrency.value}).format(Number(v))
const statusName:Record<string,string>={RELEASED:'已释放',DEFERRED:'暂缓',DEFERRED_RELEASED:'暂缓历史（已释放）',UNKNOWN:'未返回',queued:'排队中',running:'同步中',succeeded:'已完成',failed:'失败'}
const fmt=(v:any)=>v==null?'—':Number(v).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2})
const time=(v:string)=>v?new Date(v).toLocaleString('zh-CN'):'—'
let seq=0
async function load(){if(!can('finance.records'))return;const id=++seq;busy.value=true;try{const p=new URLSearchParams({store:selectedStore.value,q:q.value.trim(),status:status.value,marketplace:market.value,page:String(page.value),page_size:String(pageSize.value),currency:displayCurrency.value});p.set('days',String(days.value));const d=await api('/finance/transactions?'+p);if(id===seq){rows.value=d.rows;total.value=d.total;summary.value=d.display_summary;fx.value=d.fx;error.value=''}}catch(e){if(id===seq)error.value=(e as Error).message}finally{if(id===seq)busy.value=false}}
function search(){page.value=1;load()}
async function detail(row:any){try{selected.value=await api('/finance/transactions/'+row.id);detailOpen.value=true}catch(e){ElMessage.error((e as Error).message)}}
function flatten(items:any[],prefix=''):any[]{return (items||[]).flatMap(x=>{const label=prefix?prefix+' / '+(x.label_cn||x.breakdownType):(x.label_cn||x.breakdownType);return [{label,amount:x.breakdownAmount?.currencyAmount,currency:x.breakdownAmount?.currencyCode},...flatten(x.breakdowns,label)]})}
onMounted(async()=>{const o=await api('/options');markets.value=o.order_markets;stores.value=o.stores;await load()})
onUnmounted(()=>{seq++});watch(()=>props.store,v=>{selectedStore.value=v});watch(selectedStore,()=>{page.value=1;q.value='';load()});watch(displayCurrency,search)
</script>
<template><el-alert v-if="error" :title="error" type="error" :closable="false"/><div class="finance-toolbar"><el-radio-group v-model="view"><el-radio-button v-if="can('finance.records')" value="records">回款查询</el-radio-button><el-radio-button v-if="can('finance.summary')" value="summary">财务汇总</el-radio-button></el-radio-group></div>
<template v-if="view==='records'"><section class="panel finance-records"><form class="filters finance-filters" @submit.prevent="search"><el-input v-model="q" placeholder="输入完整亚马逊订单号" clearable class="keyword"/><el-select v-model="selectedStore" aria-label="回款店铺"><el-option v-for="s in stores" :key="s" :label="s" :value="s"/></el-select><el-select v-model="market" placeholder="全部站点" clearable style="width:135px"><el-option v-for="m in markets" :key="m" :value="m" :label="m==='IE'?'爱尔兰 IE':m==='AE'?'阿联酋 AE':m==='SA'?'沙特 SA':m"/></el-select><el-select v-model="status" placeholder="全部回款状态" clearable style="width:180px"><el-option v-for="s in ['RELEASED','DEFERRED','DEFERRED_RELEASED']" :key="s" :label="statusName[s]" :value="s"/></el-select><el-select v-model="days" aria-label="入账日期范围" @change="search"><el-option v-for="d in [1,3,7,14,30,90,180,365]" :key="d" :value="d" :label="`最近${d}天`"/></el-select><el-button native-type="submit" type="primary">查询</el-button><TableReset table-key="FinancePanel/table-1"/></form><p class="metrics-note">按最近入账时间筛选并降序展示（最近1天为过去24小时），包含非订单流水。回款可能延迟；仅汇总已同步流水，历史释放记录不能重复计入回款。展示币种：{{displayCurrency}} · 汇率参考日期：{{fx?.date||'待同步'}}。</p><div class="finance-totals"><div v-for="s in summary" :key="s.status"><span>{{statusName[s.status]}} · {{displayCurrency}}</span><b>{{money(s.amount)}}</b><small>{{s.count}} 笔 · {{s.status==='DEFERRED_RELEASED'?'历史记录，勿重复计入':'已同步流水净额'}}<template v-if="s.unknown"> · 有金额未返回</template><template v-if="s.missing_currencies?.length"> · 汇率待补齐</template></small></div></div><template v-if="true"><el-table border data-width-key="FinancePanel/table-1" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-1', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-1', column, event)" :data="rows" v-loading="busy" @row-dblclick="detail"><el-table-column :column-key="'column-2'" label="入账时间" :width="tableWidths.width('table-1', 'column-2', '180')"><template #default="{row}">{{time(row.posted_at)}}</template></el-table-column><el-table-column :column-key="'column-3'" :width="tableWidths.width('table-1', 'column-3', undefined)" label="订单号" min-width="200"><template #default="{row}"><button v-if="row.order_id" class="order-link" @click="q=row.order_id;search()">{{row.order_id}}</button><span v-else>非订单流水</span></template></el-table-column><el-table-column :column-key="'marketplace'" prop="marketplace" label="站点" :width="tableWidths.width('table-1', 'marketplace', '75')"/><el-table-column :column-key="'column-5'" :width="tableWidths.width('table-1', 'column-5', undefined)" label="订单商品 / 数量" min-width="240" align="center"><template #default="{row}"><div v-for="(item,n) in row.order_items" :key="n" class="finance-sku">{{item.sku}} <b>× {{item.quantity??'待返回'}}</b></div><span v-if="!row.order_items?.length" class="muted">{{row.order_id?'商品待同步':'非订单流水'}}</span></template></el-table-column><el-table-column :column-key="'transaction_type_cn'" :width="tableWidths.width('table-1', 'transaction_type_cn', undefined)" prop="transaction_type_cn" label="类型" min-width="130"/><el-table-column :column-key="'column-7'" :width="tableWidths.width('table-1', 'column-7', undefined)" label="状态" min-width="120"><template #default="{row}">{{statusName[row.status]||row.status}}</template></el-table-column><el-table-column :column-key="'column-8'" :width="tableWidths.width('table-1', 'column-8', undefined)" label="交易净额" min-width="140" align="center"><template #default="{row}"><b :class="{negative:Number(row.amount)<0}">{{money(row.converted?.amount)}}</b><div class="cell-sub">原币 {{row.currency}} {{fmt(row.amount)}}</div></template></el-table-column><el-table-column :column-key="'column-9'" :width="tableWidths.width('table-1', 'column-9', '90')"><template #default="{row}"><el-button link type="primary" @click="detail(row)">费用明细</el-button></template></el-table-column><template #empty><el-empty description="尚无匹配回款，可同步最近流水或指定订单"/></template></el-table></template><div class="table-footer"><span>按首页币种展示 · 净额不是银行到账或利润</span><AppPagination v-model:current-page="page" :total="total" @change="load" v-model:page-size="pageSize"/></div></section></template>
<FinanceSummaryPanel v-else-if="view==='summary'" :store="props.store"/>
<el-drawer v-model="detailOpen" title="回款及扣费明细" size="720px"><template v-if="selected"><h2>{{selected.order_id||'非订单流水'}}</h2><p>{{selected.currency}} {{fmt(selected.amount)}} · {{statusName[selected.status]||selected.status}}</p><p class="muted">流水编号 {{selected.transaction_id}}</p><p :title="selected.data.description">{{selected.data.description_cn}}</p><h3>订单包含商品</h3><p v-for="(item,n) in selected.order_items" :key="n">{{item.sku}} × {{item.quantity??'待返回'}}</p><h3>交易费用结构</h3><template v-if="true"><TableReset table-key="FinancePanel/table-3"/><el-table border data-width-key="FinancePanel/table-3" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-3', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-3', column, event)" :data="flatten(selected.data.breakdowns)"><el-table-column :column-key="'label'" :width="tableWidths.width('table-3', 'label', undefined)" prop="label" label="费用路径" min-width="260" align="center"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-3', 'column-2', undefined)" label="金额" align="center"><template #default="{row}">{{row.currency}} {{fmt(row.amount)}}</template></el-table-column></el-table></template><p class="metrics-note">上下级项目存在包含关系，不能把所有行重复相加。</p><div v-for="(i,n) in selected.data.items" :key="n"><h3>{{i.description||'商品明细 '+(Number(n)+1)}}</h3><p v-for="(c,k) in i.contexts" :key="k" class="muted">{{c.sku||c.asin||''}}<template v-if="c.quantityShipped!=null"> · 数量 {{c.quantityShipped}}</template></p><template v-if="true"><TableReset table-key="FinancePanel/table-4"/><el-table border data-width-key="FinancePanel/table-4" @header-dragend="(width: number, _old: number, column: any) => tableWidths.resize('table-4', width, column)" @header-contextmenu="(column: any, event: MouseEvent) => tableWidths.resetColumn('table-4', column, event)" :data="flatten(i.breakdowns)"><el-table-column :column-key="'label'" :width="tableWidths.width('table-4', 'label', undefined)" prop="label" label="项目"/><el-table-column :column-key="'column-2'" :width="tableWidths.width('table-4', 'column-2', undefined)" label="金额" align="center"><template #default="{row}">{{row.currency}} {{fmt(row.amount)}}</template></el-table-column></el-table></template></div></template></el-drawer></template>
